def journal_abbrev(name):
    if not name:
        return ""
    n = name.strip().lower()
    if n in JOURNAL_ABBR:
        return JOURNAL_ABBR[n]
    words = re.findall(r"[A-Za-z]{3,}", name)
    if len(words) >= 2:
        return "".join(w[0].upper() for w in words[:5])
    return re.sub(r"[^A-Za-z0-9]", "", name)[:12] or ""


def _slugify_name(s):
    return re.sub(r"[^a-z0-9]+", "-", (s or "").lower()).strip("-")


