# PDF 文件名常形如 `10_1002_adfm_77184__真正标题`，
# 前面的 DOI 段是提取器加上去的定位前缀，**不是标题的一部分**。
# ⚠️ 分隔符是**下划线**不是点（`10_1002_...`），早期写成 `10\.` 导致一条都没匹配上。
DOI_PREFIX_RE = re.compile(r"^10[_\.]\d{4,9}[_\-][A-Za-z0-9_.\-]*?__")
PLAUSIBLE_YEAR = re.compile(r"\b(19[89]\d|20[0-4]\d)\b")


def clean_title(t):
    """去掉 DOI 定位前缀、把下划线还原为空格。"""
    t = DOI_PREFIX_RE.sub("", t or "")
    t = t.replace("_", " ")
    return re.sub(r"\s+", " ", t).strip()


# 出版社式文件名：`Adv Funct Materials - 2026 - Zhang - 真正标题`
# 这类名字其实**富含元数据**（期刊 / 年份 / 首作者 / 标题），浪费掉很可惜。
PUBLISHER_NAME_RE = re.compile(
    r"^\s*(?P<journal>[^-]{3,60}?)\s+-\s+(?P<year>(?:19|20)\d{2})\s+-\s+"
    r"(?P<author>[^-]{1,40}?)\s+-\s+(?P<title>.+?)\s*$")


def parse_publisher_name(name):
    """解析 `期刊 - 年份 - 首作者 - 标题`。解析不出返回 None。"""
    m = PUBLISHER_NAME_RE.match((name or "").strip())
    if not m:
        return None
    d = m.groupdict()
    d["journal"] = d["journal"].strip()
    d["author"] = d["author"].strip()
    d["title"] = d["title"].strip()
    return d


def guess_year(*texts):
    """从若干文本里找最可能的发表年份（取最晚的合理年份）。"""
    best = ""
    for t in texts:
        for m in PLAUSIBLE_YEAR.finditer(t or ""):
            y = m.group(1)
            if y > best:
                best = y
    return best


def slug_title(title, n=42):
    """由标题生成页面名中段（保留中英文，去文件名非法字符）。"""
    t = re.sub(r"\s+", " ", (title or "")).strip()
    t = re.sub(r'[\\/:*?"<>|\[\]#^]', "", t)
    t = t.replace(" ", "-") if re.search(r"[A-Za-z]", t) else t
    return t[:n].strip("-") or "未命名"


# ---------------------------------------------------------------- 元数据抽取

def extract_from_md(path):
    """从全文 md 首页抽 DOI / 标题 / 作者行（尽力而为，抽不到就留空）。"""
    text = K.read_text(path)
    fm_raw, body = K.split_frontmatter(text)
    fm = K.parse_frontmatter(fm_raw)
    head = body[:4000]
    out = {
        "title": str(fm.get("title") or "").strip(),
        "doi": str(fm.get("doi") or "").strip(),
        "authors": [],
        "journal": str(fm.get("journal") or "").strip(),
        "year": "",
        "abstract": "",
    }
    if not out["doi"]:
        m = DOI_RE.search(head)
        if m:
            out["doi"] = m.group(0).rstrip(".")
    if not out["title"]:
        for line in body.split("\n"):
            s = line.strip().lstrip("#").strip()
            if len(s) >= 12 and not s.startswith(">"):
                out["title"] = s
                break
    # 清掉 DOI 定位前缀（`10_1002_adfm_77184__真标题` → `真标题`）
    out["title"] = clean_title(out["title"])
    base = os.path.basename(path)
    # 出版社式文件名：一次拿到 期刊 / 年份 / 首作者 / 干净标题
    pub = parse_publisher_name(out["title"]) or parse_publisher_name(
        os.path.splitext(base)[0].split("__")[-1])
    if pub:
        out["journal"] = out["journal"] or pub["journal"]
        out["year"] = out["year"] or pub["year"]
        out["title"] = pub["title"] or out["title"]
        if not out["authors"]:
            out["authors"] = [pub["author"]]
    if not out["year"]:
        out["year"] = guess_year(base, out["title"], body[:1500])
    out["journal_abbr"] = (journal_abbrev(out["journal"]) if out["journal"]
                           else guess_journal(base, fm.get("title") or ""))
    # 摘要：找 Abstract 段
    m = re.search(r"(?im)^#*\s*abstract\b[:\s]*(.{80,1200}?)(?:\n#{1,3}\s|\n\n\n)",
                  body)
    if m:
        out["abstract"] = re.sub(r"\s+", " ", m.group(1)).strip()[:600]
    out["doi"] = re.sub(r"^\W+", "", out["doi"])
    out.update(detect_si_from_md(head, path))
    return out


# ---------------------------------------------------------------- SI 证据探测

# `lit_extract.page_span_note()` 写进全文 md 头部的两种文案（单一真相源在 lit_extract）：
#   「共 12 页（正文 1-9 页，补充材料 10-12 页）」   → 提取件里**确实**含 SI 页
#   「共 9 页（正文 1-9 页，无补充材料）」           → 提取件里没有任何 SI 页
_SI_ABSENT_RE = re.compile(r"共\s*\d+\s*页（[^）]*无补充材料")
_SI_INPDF_RE = re.compile(r"共\s*(\d+)\s*页（正文\s*1-(\d+)\s*页，补充材料\s*(\d+)-(\d+)\s*页")


def detect_si_from_md(head, md_path="", cfg=None):
    """从**可核验证据**推导 `si_status`（missing / partial / present）。

    🔴 为什么必须这么做：旧版在 `build_card` 里把 `si_status` **硬写成 "missing"**
    （见 git 历史），于是每一张自动卡片都在断言一个**从未探测过的否定**。它的后果是连锁的：
      · `lit_gapscan` 的 `si-missing` 信号全部来自这个默认值 ⇒ **凭空造出缺口**；
      · `lit_extract` 自己在头部写着「补充材料 10-12 页」，卡片却说"没有 SI"；
      · `lit_fetch.fetch_si` 真下载过 `<pdf_dir>/si/*.si.pdf`，卡片也看不见。
    现在的取值规则（有证据才下结论）：
      · 独立 SI 文件存在（`<pdf_dir>/si/<stem>.si.pdf` 或同目录同名包含）→ `present`
      · 提取件头部写明含补充材料页                      → `partial`
      · 提取件头部写明"无补充材料"                        → `missing`
      · 头部没有页区间信息（旧提取件）                    → `missing`，但**记明依据缺失**
    返回 dict：`si_status` / `si_evidence`（人可核的依据文字）。
    """
    ev = ""
    status = "missing"
    m = _SI_INPDF_RE.search(head or "")
    if m:
        status, ev = "partial", f"提取件头部声明含补充材料页 {m.group(3)}-{m.group(4)} 页"
    elif _SI_ABSENT_RE.search(head or ""):
        ev = "提取件头部声明『无补充材料』"
    else:
        ev = "提取件头部无页区间信息（旧格式提取件），SI 有无未判定"

    # 独立 SI 文件优先（lit_fetch --si-dir 的产物；比"PDF 里带着 SI 页"更完整）
    si_hit = find_si_file(md_path, cfg)
    if si_hit:
        status = "present"
        ev = "已获取独立 SI 文件：" + os.path.basename(si_hit)
    return {"si_status": status, "si_evidence": ev}


def find_si_file(md_path, cfg=None):
    """在 `<pdf_dir>/si/` 下找与该全文 md 对应的独立 SI 文件（找不到返回 ""）。"""
    if not md_path:
        return ""
    try:
        c = cfg if cfg is not None else K.load_lit_config()
    except Exception:                                          # noqa: BLE001
        return ""
    pdf_dir = (c.get("paths") or {}).get("pdf_dir") or ""
    if not pdf_dir:
        return ""
    si_dir = os.path.join(pdf_dir, "si")
    if not os.path.isdir(si_dir):
        return ""
    stem = os.path.splitext(os.path.basename(md_path))[0]
    exact = os.path.join(si_dir, stem + ".si.pdf")
    if os.path.exists(exact):
        return exact
    for f in sorted(os.listdir(si_dir)):
        if f.lower().endswith(".pdf") and stem and stem in f:
            return os.path.join(si_dir, f)
    return ""


def find_candidate(doi, title, candidates):
    """在 lit_discover 候选里按 DOI（优先）或标题匹配。"""
    if not candidates:
        return None
    nd = (doi or "").strip().lower().rstrip(".")
    nt = re.sub(r"[^a-z0-9\u4e00-\u9fff]+", "", (title or "").lower())
    for c in candidates:
        cd = str(c.get("doi") or "").strip().lower().rstrip(".")
        if nd and cd and nd == cd:
            return c
    for c in candidates:
        ct = re.sub(r"[^a-z0-9\u4e00-\u9fff]+", "", str(c.get("title") or "").lower())
        if nt and ct and (nt == ct or nt in ct or ct in nt):
            return c
    return None


# ---------------------------------------------------------------- 卡片生成

def _page_doi(path):
    """读已存在 source 页 frontmatter 里的 doi（读不到返回 ""）。"""
    try:
        fm_raw, _ = K.split_frontmatter(K.read_text(path))
        return str(K.parse_frontmatter(fm_raw).get("doi") or "").strip()
    except Exception:                            # noqa: BLE001
        return ""


def resolve_page_collision(src_dir, page, new_doi, quiet=False):
    """同名 source 页已存在时的落点决策。返回 (page, exists)。

    · DOI **相同** → 判 exists（幂等：同一篇重复 ingest 不会再加卡，由调用方跳过）
    · DOI **不同** → 说明这是**两篇不同文献**（页名碰撞），加 `-2`/`-3` 后缀另建。
      旧逻辑一律当 exists 跳过 ⇒ 后一篇文献被**静默丢弃**（页名相同、DOI 不同）。

    🔴 DOI 归一必须走 kb_lib.norm_doi：库内已有 DOI 尾部粘连中文标点，
    不归一会把同一篇误判成"DOI 不同"而反复新建 `-2 -3 …`。
    """
    path = os.path.join(src_dir, f"{page}.md")
    if not os.path.exists(path):
        return page, False
    old_doi = _page_doi(path)
    if K.norm_doi(old_doi) == K.norm_doi(new_doi):
        return page, True
    base, n = page, 2
    while os.path.exists(os.path.join(src_dir, f"{base}-{n}.md")):
        n += 1
    if not quiet:
        print(f"  [!] 页面名碰撞：既有页 DOI {old_doi or '—'} ≠ 新 DOI "
              f"{new_doi or '—'} ⇒ 另建 {base}-{n}")
    return f"{base}-{n}", False


def build_card(meta, raw_rel, cfg=None, tier=None):
    """生成 source 页内容（骨架）。返回 (frontmatter_dict, page_name, body_text, notes)。

    cfg/tier 可选：给了就写 `journal_tier` 并按档位生成不同的「精读待办」。
    """
    notes = []
    year = (meta.get("year") or "").strip()
    # 🔴 DOI 一律走 kb_lib.norm_doi：库内已有 15 条 DOI 尾部粘连中文标点（。；，），
    #    本地各写一套正则会各自漏清、同一篇无法合并去重。
    doi = K.norm_doi(meta.get("doi"))
    journal = (meta.get("journal") or "").strip()
    title = (meta.get("title") or "").strip()
    authors_all = meta.get("authors_all") or meta.get("authors") or []
    if isinstance(authors_all, str):
        authors_all = [a.strip() for a in authors_all.split(";") if a.strip()]
    corres = (meta.get("corresponding_author") or "").strip()
    abstract = re.sub(r"\s+", " ", (meta.get("abstract") or "")).strip()
    # SI 证据：由调用方（extract_from_md）或候选元数据给出；缺失时**再探一次**独立 SI 文件，
    # 不能默默退回 "missing"。
    si_status = str(meta.get("si_status") or "").strip()
    si_evidence = str(meta.get("si_evidence") or "").strip()
    if si_status not in ("missing", "partial", "present"):
        probe_md = os.path.join(K.VAULT, *str(raw_rel).split("/")) if raw_rel else ""
        got = detect_si_from_md("", probe_md, cfg)
        si_status, si_evidence = got["si_status"], got["si_evidence"]

    page = f"{year or 'YYYY'}-{slug_title(title)}-{meta.get('journal_abbr') or journal_abbrev(journal) or 'NA'}"

    # —— 作者字段门禁（CLAUDE.md）：取不到就留白，不得凭印象补写
    if authors_all:
        authors = authors_all[:12]
    else:
        authors = []
        notes.append("raw 与候选元数据均无作者栏，作者未核")
    if not corres:
        notes.append("通讯作者未核")

    # —— source_url：可点击的原文/出版方链接（库内约定：优先 doi.org）
    # 🔴 只有 DOI **看起来完整**（kb_lib.doi_looks_complete：非注册号碎片）才生成链接：
    #    碎片/截断 DOI（如 `10.1002/anie`、尾点残留）拼出的 doi.org 链接打不开，
    #    写进 frontmatter 就是一条假引用。
    if doi and K.doi_looks_complete(doi):
        source_url = f"https://doi.org/{doi}"
    elif re.search(r"arxiv", (meta.get("raw_rel") or raw_rel or ""), re.I):
        mm = re.search(r"(\d{4}\.\d{4,5})", title + " " + raw_rel)
        source_url = f"https://arxiv.org/abs/{mm.group(1)}" if mm else ""
    else:
        source_url = ""

    fm = {
        "type": "source",
        "created": TODAY,
        "updated": TODAY,
        "year": year or "YYYY",
        "journal": journal or "",
        "journal_tier": tier or "",        # 🆕 分级标签（T0..T4；缺则空）
        "doi": doi,
        "source_url": source_url,
        "authors": authors,
        "corresponding_author": corres,
        "institution": "",                 # 一律留白
        "authors_source": ("字段来自 OpenAlex 候选元数据；机构未核，故留白"
                           if authors_all else
                           "作者栏未取到，字段留白待核"),
        "tags": ["source", "待精读"],
        "aliases": [title] if title else [],
        "summary": abstract[:200] if abstract else f"（待精读）{title}",
        "source_reliability": "待核：自动建卡骨架，尚未精读，数字与结论均未回溯原文",
        # 🔴 si_status 必须来自**证据**（lit_extract 的页区间声明 / 独立 SI 文件），
        #    不得再硬写 "missing"。理由见 detect_si_from_md 的 docstring。
        "si_status": si_status,
        "sources": [f"[[{raw_rel}]]"],
    }
    lines = [f"# {title or page}", ""]
    if abstract:
        lines += [abstract[:400], ""]
    else:
        lines += ["（本页为自动建卡骨架，摘要待补。）", ""]
    # SI 缺口标记（CLAUDE.md §SI 缺失标记协议要求**正文**里就地标出，此前从未实现）
    if si_status in ("missing", "partial"):
        what = "SI 完全未获取" if si_status == "missing" else "仅提取件内含部分 SI 页，独立 SI 未获取"
        lines += [f"> ⚠️ 信息缺口：{what}（依据：{si_evidence}）；"
                  f"文中若涉及补充材料中的数值/条件，须回查 SI 后方可引用。", ""]
    if notes:
        lines += [f"> ⚠️ 信息缺口：{'；'.join(notes)}。", ""]
    lines += [f"> 📄 原文：`[[{raw_rel}]]`", ""]
    if tier:
        lines += [f"> 🏷️ 期刊分级：**{tier}**（"
                  f"{(cfg.get('tiers') or {}).get(tier, {}).get('label', '') if cfg else ''}）", ""]
    lines += ["## 待精读", ""]
    if cfg is not None and tier:
        lines += todo_items(cfg, tier)
    else:
        lines += [
            "- [ ] 读原文，补 300–500 字摘要与关键要点",
            "- [ ] 逐条核验数字/性能指标（CLAUDE.md 批判性摄入三层结构）",
            "- [ ] 补 `## 诚实边界` 与 `## 批判性评估`",
            "- [ ] 把 `source_reliability` 从「待核」改为实际结论",
            "- [ ] 补 ≥2 个 `[[concepts/...]]` 出链，并在相关概念页回链本页",
        ]
    lines += [""]
    return fm, page, "\n".join(lines), notes


def render_frontmatter(fm):
    """把 dict 渲染为 YAML frontmatter 文本。

    ⚠️ 两条本库血泪铁律：
      1. 含冒号/引号的长文本字段**整体加双引号**，否则 YAML 会把冒号后当新键，
         整个 frontmatter 解析失败（曾一次写坏 49 页）；
      2. 闭合 `---` 后**必须跟换行**，否则 kb_lib._FM_RE 匹配不到
         （曾一次写坏 124 页）。
    故本函数统一走 json.dumps 做标量转义，并在末尾显式补 \n。
    """
    def scalar(v):
        s = "" if v is None else str(v)
        if re.search(r"[:#\[\]{}&*!|>'\"%@`\n]|^\s|\s$", s) or s.strip() != s:
            return json.dumps(s, ensure_ascii=False)
        return s

    out = ["---"]
    for k, v in fm.items():
        if isinstance(v, list):
            if not v:
                out.append(f"{k}: []")
                continue
            out.append(f"{k}:")
            for item in v:
                out.append(f"  - {scalar(item)}")
        else:
            out.append(f"{k}: {scalar(v)}")
    out.append("---")
    out.append("")                      # 保证闭合 --- 后有换行
    return "\n".join(out)


# ---------------------------------------------------------------- 主流程

def suggest_links(page, k=8, index=None):
    """用检索层找最相关的既有页面，作为强制补链的候选。

    ⚠️ 两个曾经的静默失效（2026-10-10 修）：
      1. `KS.load_index()` 在**每一页**都被调用一次 —— meta.json(~400 KB) + bm25.json
         被反复读取解析；一批 72 页就是 72 次。现在由调用方传入已加载的 `index`。
      2. `load_index()` 在 BM25 索引缺失时调 `sys.exit(2)`，而这里 `except Exception`
         **接不住 SystemExit**（它是 BaseException）⇒ `--apply` 会在写到一半时整体中止，
         既没有写后复核，也没有去重刷新。现在预检 + 捕获 BaseException 并降级。
    """
    if index is None:
        try:
            import kb_search as KS
            if not (os.path.exists(K.META_PATH) and os.path.exists(K.BM25_PATH)):
                print("  [!] BM25 索引缺失，跳过补链建议"
                      "（先跑 python tools/kb_build_index.py）", file=sys.stderr)
                return []
            index = KS.load_index()
        except BaseException as e:                    # noqa: BLE001  （SystemExit 也在此列）
            print(f"  [!] 检索层不可用，跳过补链建议：{type(e).__name__}: {e}",
                  file=sys.stderr)
            return []
    try:
        import kb_search as KS
        meta, bm = index
        hits = KS.resolve_aliases(page, meta.get("alias_map", {}))
        strong = [(a, c) for a, c in hits if len(a) >= 3] or hits[:1]
        canon = [c for _, c in strong if c != page]
        qt = K.tokenize(page)
        for c in canon:
            qt.extend(K.tokenize(c))
        ranked = KS.bm25_score(qt, bm, canon, query_raw=page)
        out = []
        for name, _ in ranked:
            if name == page:
                continue
            t = KS.meta_of(meta, name)[4]
            if t in ("concept", "topic"):
                out.append(name)
            if len(out) >= k:
                break
        return out
    except BaseException as e:                        # noqa: BLE001
        print(f"  [!] 补链建议失败（不中止批次）：{type(e).__name__}: {e}", file=sys.stderr)
        return []


# ---------------------------------------------------------------- 骨架门禁

def _outlinks(body):
    """正文里指向**页面**的 wikilink 数（资源回链 `[[raw/...]]` 不算）。"""
    links = []
    for m in re.finditer(r"\[\[([^\]\|#]+)", K.strip_code(body)):
        t = m.group(1).strip().rstrip("\\/").replace("\\", "/")
        if t.startswith("raw/") or t.endswith((".md", ".pdf", ".png", ".jpg")):
            continue
        links.append(t)
    return links


def _inlink_count(page, exclude=()):
    """全库有多少页面链接到 `page`（按 basename 比对，与 kb_lint 的解析口径一致）。"""
    n = 0
    for d in K.PAGE_DIRS:
        dd = os.path.join(K.WIKI, d)
        if not os.path.isdir(dd):
            continue
        for f in os.listdir(dd):
            if not f.endswith(".md") or f[:-3] in exclude:
                continue
            try:
                txt = K.read_text(os.path.join(dd, f))
            except OSError:
                continue
            if re.search(r"\[\[[^\]\|#]*" + re.escape(page) + r"(?:\||\]\])", txt):
                n += 1
                if n >= 1:
                    return n
    return n


def gate_cards(written, planned, strict_backlinks=True):
    """骨架门禁：把 CLAUDE.md 的建卡纪律变成**判定**，而不是打印。

    🔴 为什么要有这个函数：`CLAUDE.md` §操作流程 6 与 lit-watch skill 都写着
    「每个新建页面至少链接到 2 个已有页面，且本身获得至少 1 条入站链接」，
    但旧代码只 `print("建议补链: …")` —— 纪律写了、代码没查，等于没有纪律。
    实测：自动建的卡出站恒为 1 条（只有 `sources:` 里那条 `[[raw/text/...]]`），入站 0。

    判定分两级（**硬 vs 软**），因为两类问题性质不同：
      · **硬**（结构坏了、页面不可用）→ 非零退出，必须修：
        frontmatter 不可解析 / 缺 type / authors 不是 list / `sources:` 首条不是
        `[[raw/...]]` / 回链文件在盘上不存在。
      · **软**（纪律未完成、但页面本身完好）→ 记入门禁报告并返回 exit 2：
        出站页面链接 < 2、入站 = 0。**不自动替人补链**（那会凭空造出错误关联），
        只把缺口写成机器可读的报告 + 待办，逼下一轮精读时处理。

    返回 (hard: list, soft: list)。
    """
    hard, soft = [], []
    for item in planned:
        t = item["target"]
        name = item["page"]
        p = os.path.join(K.VAULT, *t.split("/"))
        if item.get("exists"):
            continue
        if not os.path.exists(p):
            hard.append((name, "文件未落盘"))
            continue
        txt = K.read_text(p)
        fmr, body = K.split_frontmatter(txt)
        fm = K.parse_frontmatter(fmr)
        if not fm.get("type"):
            hard.append((name, "frontmatter 不可解析或缺 type"))
        au = fm.get("authors")
        if au is not None and not isinstance(au, list):
            hard.append((name, f"authors 不是列表（{type(au).__name__}）"))
        src = fm.get("sources") or []
        first = str(src[0]) if src else ""
        if not re.match(r"^\[\[raw/", first):
            hard.append((name, f"sources 首条不是 [[raw/...]]：{first[:60]}"))
        else:
            rel = first[2:].split("]]")[0].replace("\\", "/").rstrip("/")
            if rel and not os.path.exists(os.path.join(K.VAULT, *rel.split("/"))):
                hard.append((name, f"sources 回链指向不存在的文件：{rel}"))
        outs = [x for x in _outlinks(body) if x != name]
        if len(outs) < 2:
            soft.append((name, f"出站页面链接 {len(outs)} < 2（仅 raw 回链不算）"))
        if _inlink_count(name) < 1:
            soft.append((name, "入站链接 0（无任何既有页面指向它）"))
    return hard, soft


def write_gate_report(written, planned, hard, soft):
    """把门禁结果写成机器可读报告（落在 runs_dir/runs/，不落归档层）。"""
    try:
        cfg = K.load_lit_config()
    except Exception:                                          # noqa: BLE001
        cfg = {}
    out_dir = K.lit_runs_dir(cfg, "runs")
    os.makedirs(out_dir, exist_ok=True)
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
    p = os.path.join(out_dir, f"gate-{stamp}.json")
    payload = {"at": datetime.datetime.now().isoformat(timespec="seconds"),
               "written": written,
               "hard": [{"page": a, "why": b} for a, b in hard],
               "soft": [{"page": a, "why": b} for a, b in soft]}
    tmp = p + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)
    os.replace(tmp, p)
    return p


def selftest():
    global HERE          # 9b 会把 HERE 临时指向桩目录以验证「存在才跑」两个分支
    print("=== lit_ingest --selftest ===")
    ok = True
    # 1) frontmatter 渲染必须能被 kb_lib 解析回来（用同一个解析器复核）
    fm = {"type": "source", "summary": "含冒号: 的内容", "authors": ["A B", "C D"],
          "year": "2026", "tags": ["source"]}
    txt = render_frontmatter(fm) + "# 标题\n正文\n"
    raw_fm, body = K.split_frontmatter(txt)
    parsed = K.parse_frontmatter(raw_fm)
    good = (parsed.get("type") == "source" and parsed.get("year") == "2026"
            and len(parsed.get("authors") or []) == 2
            and "含冒号" in str(parsed.get("summary")))
    print(f"  [{'ok' if good else 'FAIL'}] frontmatter 往返解析（含冒号标量）")
    ok = ok and good
    good2 = body.lstrip().startswith("# 标题")
    print(f"  [{'ok' if good2 else 'FAIL'}] 闭合 --- 后换行正确（正文独立）")
    ok = ok and good2
    # 2) 期刊缩写
    for name, want in (("Nature Communications", "NatCommun"),
                       ("Advanced Functional Materials", "AFM"),
                       ("Journal of the American Chemical Society", "JACS")):
        got = journal_abbrev(name)
        print(f"  [{'ok' if got == want else 'FAIL'}] {name} -> {got}")
        ok = ok and got == want
    # 3) 作者门禁：无作者时必须留白且标缺口
    f2, page2, body2, notes2 = build_card(
        {"title": "Some Paper Title", "year": "2026", "journal": "Nature"}, "raw/text/x.md")
    gate = (f2["authors"] == [] and f2["institution"] == "" and notes2)
    print(f"  [{'ok' if gate else 'FAIL'}] 无作者时留白并标信息缺口（authors={f2['authors']}）")
    ok = ok and gate
    # 4) 反例：不得自动写结论
    no_concl = ("## 待精读" in body2) and ("已证明" not in body2)
    print(f"  [{'ok' if no_concl else 'FAIL'}] 正文只含占位、不含结论")
    ok = ok and no_concl
    # 5) 回链格式
    backlink_ok = f2["sources"][0] == "[[raw/text/x.md]]"
    print(f"  [{'ok' if backlink_ok else 'FAIL'}] sources 首条为 [[raw/...]] "
          f"（{f2['sources'][0]}）")
    ok = ok and backlink_ok
    # 6) 落盘路径必须是**相对库根**：target 只允许以 `wiki/sources/` 开头，
    #    且 join 后不得二次出现库根名（回归夹具，2026-10-05 影子目录事故）。
    src_rel = "wiki/sources"
    target = f"{src_rel}/2026-X-NatCommun.md"
    joined = os.path.join(K.VAULT, *target.split("/"))
    no_double = joined.count(os.path.basename(K.VAULT)) == 1 and target.startswith("wiki/")
    print(f"  [{'ok' if no_double else 'FAIL'}] 落盘路径不重复库根（{joined}）")
    ok = ok and no_double
    # 反例：若误把绝对 src_dir 拼进 target，join 后必须能察觉重复
    bad_target = f"{os.path.join(K.VAULT, 'wiki', 'sources')}/2026-X.md".replace("\\", "/")
    bad_joined = os.path.join(K.VAULT, *bad_target.split("/"))
    caught = bad_joined.count(os.path.basename(K.VAULT)) > 1
    print(f"  [{'ok' if caught else 'FAIL'}] 反例 绝对 target 会被检出重复库根")
    ok = ok and caught
    # 7) source_url：有 DOI 时必须是可点击的 doi.org 链接；无 DOI 时留空
    f3, _, _, _ = build_card(
        {"title": "X", "year": "2026", "journal": "Nature",
         "doi": "10.1002/adma.73843"}, "raw/text/x.md")
    su_ok = f3.get("source_url") == "https://doi.org/10.1002/adma.73843"
    print(f"  [{'ok' if su_ok else 'FAIL'}] 有 DOI → source_url 为 doi.org 链接"
          f"（{f3.get('source_url')}）")
    ok = ok and su_ok
    f4, _, _, _ = build_card(
        {"title": "Y", "year": "2026", "journal": "Nature", "doi": ""}, "raw/text/y.md")
    su_none = f4.get("source_url") in ("", None)
    print(f"  [{'ok' if su_none else 'FAIL'}] 无 DOI → source_url 留空"
          f"（{f4.get('source_url')!r}）")
    ok = ok and su_none
    # 7b) DOI 归一 + 完整性门禁（2026-10-06 回归夹具）：
    #     · 尾部粘连中文标点的 DOI 必须被清洗（否则永远无法与其它来源合并）
    #     · 注册号碎片（10.1002/anie）不得生成打不开的 doi.org 链接
    f5, _, _, _ = build_card(
        {"title": "P", "year": "2026", "journal": "Angewandte Chemie Int. Ed.",
         "doi": "10.1002/adma.73843。"}, "raw/text/p.md")
    good = f5.get("doi") == "10.1002/adma.73843"
    print(f"  [{'ok' if good else 'FAIL'}] DOI 尾部中文标点被归一（{f5.get('doi')!r}）")
    ok = ok and good
    good = f5.get("source_url") == "https://doi.org/10.1002/adma.73843"
    print(f"  [{'ok' if good else 'FAIL'}] 归一后可生成 doi.org 链接（{f5.get('source_url')!r}）")
    ok = ok and good
    f6, _, _, _ = build_card(
        {"title": "Q", "year": "2026", "journal": "Angewandte Chemie Int. Ed.",
         "doi": "https://doi.org/10.1002/anie"}, "raw/text/q.md")
    good = f6.get("source_url") == ""
    print(f"  [{'ok' if good else 'FAIL'}] 反例 注册号碎片 DOI 不生成链接"
          f"（doi={f6.get('doi')!r} url={f6.get('source_url')!r}）")
    ok = ok and good
    # 7c) 页面名碰撞：DOI 相同 → 幂等跳过；DOI 不同 → 加 -2 后缀，不丢文献
    import uuid
    tsrc = os.path.join(HERE, f"_selftest_src_{uuid.uuid4().hex[:8]}")
    os.makedirs(tsrc, exist_ok=True)
    try:
        ex_page = "2026-Collide-Nature"
        with open(os.path.join(tsrc, f"{ex_page}.md"), "w", encoding="utf-8") as fh:
            fh.write(render_frontmatter({"type": "source", "doi": "10.1038/aaa.1"}) + "# 旧\n")
        p_same, exists_same = resolve_page_collision(tsrc, ex_page, "10.1038/aaa.1")
        good = (p_same == ex_page) and exists_same
        print(f"  [{'ok' if good else 'FAIL'}] 碰撞 DOI 相同 → 判 exists 幂等跳过（{p_same}）")
        ok = ok and good
        p_diff, exists_diff = resolve_page_collision(tsrc, ex_page, "10.1038/bbb.2",
                                                     quiet=True)
        good = (p_diff == ex_page + "-2") and not exists_diff
        print(f"  [{'ok' if good else 'FAIL'}] 碰撞 DOI 不同 → 另建 -2（{p_diff}）")
        ok = ok and good
        # 反例：DOI 尾部标点差异不得被误判为"不同"（否则每跑一次就多建一篇）
        p_punc, exists_punc = resolve_page_collision(tsrc, ex_page, "10.1038/aaa.1。",
                                                     quiet=True)
        good = (p_punc == ex_page) and exists_punc
        print(f"  [{'ok' if good else 'FAIL'}] 反例 DOI 尾标点差异仍判同一篇（{p_punc}）")
        ok = ok and good
        # 已占用 -2 时下一个应取 -3
        open(os.path.join(tsrc, f"{ex_page}-2.md"), "w", encoding="utf-8").write("x")
        p_next, _ = resolve_page_collision(tsrc, ex_page, "10.1038/ccc.3", quiet=True)
        good = p_next == ex_page + "-3"
        print(f"  [{'ok' if good else 'FAIL'}] -2 已占用则取 -3（{p_next}）")
        ok = ok and good
    finally:
        for f in os.listdir(tsrc):
            try:
                os.remove(os.path.join(tsrc, f))
            except Exception:                     # noqa: BLE001
                pass
        try:
            os.rmdir(tsrc)
        except Exception:                         # noqa: BLE001
            pass
    # 8) 期刊分级（2026-10-06）：cand 的 journal_tier 必须写进 frontmatter；
    #    T0/T1 必须走增强精读（待办含 critic / SI / concept 三项）。
    # 🔴 夹具必须**自带**配置，不能读生产 lit_config.yaml：
    #    旧版用真实配置，于是"改白名单/改档位"会让本自检 FAIL——校验器依赖被校验系统的
    #    现状，是 CLAUDE.md §校验器自检纪律明确点名的一类腐坏（同型事故已 7 次）。
    cfg = {
        "journals": [{"issn_l": "0028-0836", "name": "Nature", "tier": "T0"},
                     {"issn_l": "0947-7047", "name": "Ionics", "tier": "T4"}],
        "tiers": {"T0": {"label": "夹具正刊", "relevance_min": 0.40,
                         "ingest_depth": "enhanced", "uncapped": True},
                  "T4": {"label": "夹具专业刊", "relevance_min": 0.70,
                         "ingest_depth": "light"}},
        "default_tier": "T3",
        "paths_rel": {"text_dir": "raw/text"}, "paths": {},
        "layout": {"source_page_dir": "wiki/sources",
                   "source_page_backlink_prefix": "raw/text"},
    }
    fc, _, bc, _ = build_card(
        {"title": "Z", "year": "2026", "journal": "Nature", "doi": "10.1038/x"},
        "raw/text/z.md", cfg=cfg, tier="T0")
    tier_ok = fc.get("journal_tier") == "T0"
    print(f"  [{'ok' if tier_ok else 'FAIL'}] frontmatter 写入 journal_tier（{fc.get('journal_tier')}）")
    ok = ok and tier_ok
    enh = ("critic" in bc) and ("SI" in bc) and ("concept" in bc)
    print(f"  [{'ok' if enh else 'FAIL'}] T0 骨架走增强精读（含 critic/SI/concept 待办）")
    ok = ok and enh
    # 反例：T4 骨架**不得**含增强项
    f4b, _, b4, _ = build_card(
        {"title": "W", "year": "2026", "journal": "Ionics", "doi": "10.1007/x"},
        "raw/text/w.md", cfg=cfg, tier="T4")
    not_enh = ("critic" not in b4) and (f4b.get("journal_tier") == "T4")
    print(f"  [{'ok' if not_enh else 'FAIL'}] 反例 T4 骨架不含增强项")
    ok = ok and not_enh
    # resolve_tier：候选带 tier 优先；否则按刊名反查；未知刊回退默认档
    rt = resolve_tier({"journal_tier": "T1"}, {}, cfg)
    print(f"  [{'ok' if rt == 'T1' else 'FAIL'}] resolve_tier 候选优先（{rt}）")
    ok = ok and rt == "T1"
    rt2 = resolve_tier(None, {"journal": "Nature"}, cfg)
    print(f"  [{'ok' if rt2 == 'T0' else 'FAIL'}] resolve_tier 按刊名反查（Nature→{rt2}）")
    ok = ok and rt2 == "T0"
    rt3 = resolve_tier(None, {"journal": "某不存在的刊"}, cfg)
    print(f"  [{'ok' if rt3 == cfg.get('default_tier') else 'FAIL'}] 反例 未知刊回退默认档（{rt3}）")
    ok = ok and rt3 == cfg.get("default_tier")

    # 8b) SI 证据探测（2026-10-10）：si_status 必须**来自证据**，不得默认 missing。
    #     正例：头部声明含补充材料页 → partial；反例：声明「无补充材料」→ missing；
    #     无页区间信息 → missing 但依据写"未判定"。
    si1 = detect_si_from_md("共 12 页（正文 1-9 页，补充材料 10-12 页）", cfg={})
    c1 = si1["si_status"] == "partial" and "10-12" in si1["si_evidence"]
    print(f"  [{'ok' if c1 else 'FAIL'}] SI 正例：头部声明含补充材料 → partial（{si1}）")
    ok = ok and c1
    si2 = detect_si_from_md("共 9 页（正文 1-9 页，无补充材料）", cfg={})
    c2 = si2["si_status"] == "missing" and "无补充材料" in si2["si_evidence"]
    print(f"  [{'ok' if c2 else 'FAIL'}] SI 反例：头部声明无补充材料 → missing（{si2}）")
    ok = ok and c2
    si3 = detect_si_from_md("（旧格式提取件，没有页区间信息）", cfg={})
    c3 = si3["si_status"] == "missing" and "未判定" in si3["si_evidence"]
    print(f"  [{'ok' if c3 else 'FAIL'}] SI 无依据时如实标注未判定（{si3}）")
    ok = ok and c3
    # 卡片正文必须带 SI 缺口标记（CLAUDE.md §SI 缺失标记协议；旧版从未实现）
    _fs, _, _bs, _ = build_card({"title": "SI Gap Probe Paper", "year": "2026",
                                 "journal": "Nature", "si_status": "missing",
                                 "si_evidence": "夹具：无补充材料"},
                                "raw/text/si-probe.md", cfg=cfg, tier="T0")
    c4 = ("⚠️ 信息缺口" in _bs) and ("SI" in _bs) and _fs["si_status"] == "missing"
    print(f"  [{'ok' if c4 else 'FAIL'}] 卡片正文就地标出 SI 缺口")
    ok = ok and c4

    # 8c) 骨架门禁的链接口径：`[[raw/...]]` 资源回链**不算**页面出站链接。
    c5 = _outlinks("[[concepts/固态电解质]] 与 [[concepts/机器学习势函数|MLIP]]\n"
                   "见 `[[concepts/这是代码示例]]`\n[[raw/text/x.md]]") == \
        ["concepts/固态电解质", "concepts/机器学习势函数"]
    print(f"  [{'ok' if c5 else 'FAIL'}] 出站链接口径（页面算、raw 不算、代码块不算）")
    ok = ok and c5

    # 9) 入库后自动重跑去重清单：两个被调工具必须**真实存在**（否则静默 no-op）
    dep_ok = all(os.path.exists(os.path.join(HERE, t))
                 for t in ("kb_dois.py", "lit_catalogue.py"))
    print(f"  [{'ok' if dep_ok else 'FAIL'}] refresh_dedup 依赖工具存在（kb_dois/lit_catalogue）")
    ok = ok and dep_ok
    # 9b) --with-index 的收尾子步骤：**存在才跑**（不存在不得凭空多一个失败步骤）
    #     用具名桩文件 + 临时 HERE 验证两个分支，不动本目录的既有文件。
    import shutil as _shutil
    import tempfile

    def _mkprobe(prefix):
        # 注意：不要用 tempfile.mkdtemp(dir=...)。本机实测在受限环境下
        # 「mkdtemp 建的目录」里写文件会被拒（能建目录、不能写），而 os.makedirs 建的可以；
        # 所以这里统一用 os.makedirs，并逐级回退：系统临时目录 → 当前目录 → 工具目录。
        import uuid as _uuid
        last = None
        for base in (tempfile.gettempdir(), os.getcwd(), HERE):
            d = os.path.join(base, prefix + _uuid.uuid4().hex[:8])
            try:
                os.makedirs(d, exist_ok=True)
                probe_f = os.path.join(d, ".w")
                with open(probe_f, "w", encoding="utf-8") as fh:
                    fh.write("x")
                os.remove(probe_f)
                return d
            except OSError as e:                               # noqa: BLE001
                last = e
                continue
        raise OSError(f"找不到可写的临时目录：{last}")

    probe_empty = _mkprobe("lit_ingest_selftest_empty_")
    probe_stub = _mkprobe("lit_ingest_selftest_stub_")
    try:
        # 空桩目录：两个可选步骤都不该出现（真实知识库里这两个脚本本来就在，
        # 所以必须用显式 here= 注入，否则这条断言在本库里永远不成立）
        absent = dict(_dedup_steps(True, ["2026-X-Nature"], here=probe_empty))
        good = ("kb_corpus.py" not in absent) and ("kb_semantic_search.py" not in absent)
        print(f"  [{'ok' if good else 'FAIL'}] 桩缺失时收尾步骤不含 kb_corpus/kb_semantic_search")
        ok = ok and good
        # 9c) qc_base_check.py 是**无条件**守卫（与有无新页/有无索引无关），
        #     存在即须入链——防 2026-10-10 那类「库外误改 .base 静默失真」。
        for stub in ("kb_corpus.py", "kb_semantic_search.py", "qc_base_check.py"):
            with open(os.path.join(probe_stub, stub), "w", encoding="utf-8") as fh:
                fh.write("# 桩\n")
        uncond = dict(_dedup_steps(False, [], here=probe_stub))
        good = "qc_base_check.py" in uncond
        print(f"  [{'ok' if good else 'FAIL'}] qc_base_check.py 无条件入链（无新页/无索引也跑）")
        ok = ok and good
        good = "qc_base_check.py" not in absent
        print(f"  [{'ok' if good else 'FAIL'}] 反例 桩缺失时收尾步骤不含 qc_base_check")
        ok = ok and good
        present = dict(_dedup_steps(True, ["2026-X-Nature"], here=probe_stub))
        good = ("kb_corpus.py" in present) and (present["kb_corpus.py"][-1] == "--build")
        print(f"  [{'ok' if good else 'FAIL'}] kb_corpus.py 存在 → 跑 `--build`")
        ok = ok and good
        sem_cmd = present.get("kb_semantic_search.py") or []
        good = ("--add" in sem_cmd) and sem_cmd[-1:] == ["2026-X-Nature"]
        print(f"  [{'ok' if good else 'FAIL'}] kb_semantic_search.py 存在 → 带 `--add <新页名>`")
        ok = ok and good
        # 反例：不给新页名时不得跑 `--add`（无参数的空命令）
        good = "kb_semantic_search.py" not in dict(
            _dedup_steps(True, [], here=probe_stub))
        print(f"  [{'ok' if good else 'FAIL'}] 反例 无新页时不跑语义索引步骤")
        ok = ok and good
    finally:
        _shutil.rmtree(probe_empty, ignore_errors=True)
        _shutil.rmtree(probe_stub, ignore_errors=True)
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def _dedup_steps(do_index=False, new_pages=None, here=None):
    """收尾要跑的子步骤清单（与执行分离，便于 selftest 断言"存在才跑"）。

    基础两步：kb_dois.py（库内已建卡 DOI 清单）+ lit_catalogue.py（本机文献目录）。
    基础之后追加 qc_base_check.py（Obsidian Bases 选中集合 + 漂移校验）——**无条件**跑，
    守卫的是「库外误改 .base 过滤器」这类静默失效（2026-10-10 误操作事故：
    `数据库.base` 总览被塞 hasLink 收窄至 33 页），与是否有新页无关。
    `--with-index` 时除 kb_build_index.py 外，**同目录存在**才追加：
      · kb_corpus.py          → `--build`（重建语料）
      · kb_semantic_search.py → `--add <本次新页>`（新页名去掉 .md；无语义检索时跳过）
    不覆盖既有语料/索引是本条的目的：新页入库后必须让语料与语义索引**一并更新**。
    """
    py = sys.executable
    base = here or HERE          # here 仅供自检注入桩目录；正常运行用模块 HERE
    steps = [("kb_dois.py", [py, os.path.join(base, "kb_dois.py")]),
             ("lit_catalogue.py", [py, os.path.join(base, "lit_catalogue.py")])]
    basechk = os.path.join(base, "qc_base_check.py")
    if os.path.exists(basechk):
        steps.append(("qc_base_check.py", [py, basechk]))
    if do_index:
        steps.append(("kb_build_index.py", [py, os.path.join(base, "kb_build_index.py")]))
        corpus = os.path.join(base, "kb_corpus.py")
        if os.path.exists(corpus):
            steps.append(("kb_corpus.py", [py, corpus, "--build"]))
        sem = os.path.join(base, "kb_semantic_search.py")   # 与 corpus 同步用 base（曾经用 HERE，导致自检注入桩目录时这条永远不成立）
        if os.path.exists(sem) and new_pages:
            steps.append(("kb_semantic_search.py", [py, sem, "--add"] + list(new_pages)))
    return steps


def refresh_dedup(do_index=False, new_pages=None):
    """入库后自动重跑去重清单，把新文献纳入**下次** lit-watch 去重。

    跑 `_dedup_steps()` 里的子工具（各自独立进程，互不污染）。
    幂等：无论跑几次、无新页时跑，都只是重算清单；失败仅告警、不阻断，
    每个子步骤都打印耗时（秒），便于判断是哪一步拖慢/挂住。
    """
    env = dict(os.environ, PYTHONIOENCODING="utf-8")
    results = []
    for name, cmd in _dedup_steps(do_index, new_pages):
        t0 = time.time()
        try:
            r = subprocess.run(cmd, cwd=K.VAULT, env=env,
                               capture_output=True, text=True,
                               encoding="utf-8", errors="replace", timeout=600)
            tail = (r.stdout or r.stderr or "").strip().splitlines()
            summary = tail[-1] if tail else ""
            results.append((name, r.returncode == 0, f"{summary}（{time.time() - t0:.1f}s）"))
        except Exception as e:                    # noqa: BLE001
            results.append((name, False,
                            f"{type(e).__name__}: {e}（{time.time() - t0:.1f}s）"))
    return results


def main():
    ap = argparse.ArgumentParser(description="全文 → source 卡骨架")
    ap.add_argument("--files", nargs="*", default=[], help="要建卡的 raw md（相对库根）")
    ap.add_argument("--candidates", default="", help="lit_discover 产出的候选 JSON")
    ap.add_argument("--all-text", action="store_true",
                    help="扫描 raw/text/ 下尚未建卡的全部 md")
    ap.add_argument("--apply", action="store_true", help="真正写盘（默认干跑）")
    ap.add_argument("--with-index", action="store_true",
                    help="入库后额外重建 BM25 检索索引（默认只重跑去重清单）")
    ap.add_argument("--no-links", action="store_true", help="不自动建议补链")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    cfg = K.load_lit_config()
    text_dir = cfg["paths"]["text_dir"]
    layout = cfg.get("layout") or {}
    src_rel = layout.get("source_page_dir", "wiki/sources")
    src_dir = os.path.join(K.VAULT, *src_rel.split("/"))
    backlink_prefix = layout.get("source_page_backlink_prefix",
                                 cfg["paths_rel"].get("text_dir", "raw/text"))

    candidates = []
    # 🔴 旧写法 `if args.candidates and os.path.exists(...)`：传了 --candidates 但路径写错/
    #    文件没生成时**静默降级**成"没有元数据"，建出的卡片缺作者/摘要却毫无提示。
    if args.candidates:
        if not os.path.exists(args.candidates):
            ap.error(f"候选 JSON 不存在：{args.candidates}")
        with open(args.candidates, encoding="utf-8") as f:
            candidates = json.load(f).get("papers") or []
        print(f"[i] 候选元数据 {len(candidates)} 条 ← {args.candidates}")

    files = list(args.files)
    if args.all_text or not files:
        existing_raw = set()
        if os.path.isdir(src_dir):
            for f in os.listdir(src_dir):
                if f.endswith(".md"):
                    t = K.read_text(os.path.join(src_dir, f))
                    fmr, _ = K.split_frontmatter(t)
                    for s in (K.parse_frontmatter(fmr).get("sources") or []):
                        m = re.search(r"\[\[(raw/[^\]]+)\]\]", str(s))
                        if m:
                            existing_raw.add(m.group(1))
        for f in sorted(os.listdir(text_dir)) if os.path.isdir(text_dir) else []:
            if not f.endswith(".md"):
                continue
            rel = f"{backlink_prefix}/{f}".replace("\\", "/")
            if rel not in existing_raw:
                files.append(rel)

    if not files:
        print("[ok] 没有待建卡的全文（raw/text 下均已建卡）")
        return 0

    print(f"\n{'（干跑）' if not args.apply else ''}待建卡 {len(files)} 篇\n")
    planned, written = [], []
    # 🔴 检索索引**只加载一次**（旧版每页调一次 suggest_links ⇒ 每页重读 400 KB meta +
    #    5 MB bm25；一批 72 页就是 72 次）。索引缺失时降级为"无建议"，绝不中止批次。
    link_index = None
    if not args.no_links:
        try:
            import kb_search as KS
            if os.path.exists(K.META_PATH) and os.path.exists(K.BM25_PATH):
                link_index = KS.load_index()
            else:
                print("[!] BM25 索引缺失 ⇒ 本轮不产生补链建议"
                      "（先跑 python tools/kb_build_index.py）", file=sys.stderr)
        except BaseException as e:                    # noqa: BLE001（SystemExit 也在此列）
            print(f"[!] 检索层不可用 ⇒ 本轮不产生补链建议：{type(e).__name__}: {e}",
                  file=sys.stderr)
    for rel in files:
        rel = rel.replace("\\", "/")
        abs_ = os.path.join(K.VAULT, *rel.split("/"))
        if not os.path.exists(abs_):
            print(f"  [!] 不存在，跳过: {rel}")
            continue
        meta = extract_from_md(abs_)
        cand = find_candidate(meta.get("doi"), meta.get("title"), candidates)
        if cand:
            meta.update({k: cand.get(k) for k in
                         ("authors_all", "corresponding_author", "journal",
                          "abstract") if cand.get(k)})
            meta["title"] = cand.get("title") or meta["title"]
            pd = str(cand.get("publication_date") or "")
            if pd[:4].isdigit():
                meta["year"] = pd[:4]
            meta["doi"] = cand.get("doi") or meta["doi"]
        tier = resolve_tier(cand, meta, cfg)
        fm, page, body, notes = build_card(meta, rel, cfg=cfg, tier=tier)
        # 🔴 target 必须是**相对库根**的路径（`wiki/sources/<page>.md`）。
        #   此前写成 `f"{src_dir}/{page}.md"`，而 src_dir 已是绝对路径 ⇒ 落盘时
        #   再 os.path.join(K.VAULT, *target.split("/")) 会拼出
        #   `<VAULT>/<VAULT>/wiki/sources/...`（第二次出现库根名），
        #   于是在库内嵌出一个以库根名命名的影子目录，
        #   而写后复算也走同一坏路径 ⇒ **复核"通过"却写错了地方**（2026-10-05 实测）。
        target = f"{src_rel}/{page}.md".replace("\\", "/")
        exists = os.path.exists(os.path.join(K.VAULT, *target.split("/")))
        # 🔴 页面名碰撞：同名页已存在时**不能一律当 exists 跳过**——若 DOI 不同，
        #    那是两篇不同文献，跳过等于静默丢一篇。改由 resolve_page_collision 定夺
        #    （DOI 相同 → 幂等跳过；不同 → 加 -2/-3 后缀）。
        if exists:
            page, exists = resolve_page_collision(src_dir, page, fm["doi"])
            target = f"{src_rel}/{page}.md".replace("\\", "/")
        links = [] if args.no_links else suggest_links(page, index=link_index)
        planned.append({"raw": rel, "page": page, "target": target,
                        "exists": exists, "links": links, "notes": notes,
                        "doi": fm["doi"], "year": fm["year"]})
        print(f"  {'[已存在]' if exists else '[新建] '} {page}")
        print(f"           ← {rel}")
        print(f"           DOI {fm['doi'] or '—'}  年 {fm['year']}"
              f"  期刊 {fm['journal'] or '—'}  [{tier}]")
        if notes:
            print(f"           ⚠️ {'；'.join(notes)}")
        if links:
            print(f"           建议补链: {', '.join(links[:4])}")
        if args.apply and not exists:
            dst = os.path.join(K.VAULT, *target.split("/"))
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            # 原子写：tmp + os.replace。中途被杀不会留下半截卡片
            # （半截卡片的 frontmatter 解析不出来，会被 lint 当成"页面没元数据"）。
            tmp_p = dst + ".tmp"
            with open(tmp_p, "w", encoding="utf-8", newline="") as f:
                f.write(render_frontmatter(fm) + body)
            os.replace(tmp_p, dst)
            written.append(target)

    if args.apply:
        # 写后复算：写 N 篇就要能读出 N 篇（CLAUDE.md 写盘铁律）
        bad = []
        for t in written:
            p = os.path.join(K.VAULT, *t.split("/"))
            if not os.path.exists(p):
                bad.append(t)
                continue
            fmr, _ = K.split_frontmatter(K.read_text(p))
            if not K.parse_frontmatter(fmr).get("type"):
                bad.append(t + "（frontmatter 解析失败）")
        print(f"\n[ok] 写入 {len(written)} 篇")
        if bad:
            print(f"[FAIL] {len(bad)} 篇写后复核未通过：{bad}")
            return 1
        print("     写后复核通过（N 写 = N 读，frontmatter 可解析）")

        # —— 骨架门禁（把 CLAUDE.md 的建卡纪律变成判定，而不是打印）——
        hard, soft = gate_cards(written, planned)
        rep = ""
        try:
            rep = write_gate_report(written, planned, hard, soft)
        except OSError as e:
            print(f"[warn] 门禁报告写不进去：{e}", file=sys.stderr)
        if hard:
            print(f"[FAIL] 骨架门禁（硬）：{len(hard)} 项")
            for a, b in hard[:10]:
                print(f"       · {a}：{b}")
        if soft:
            print(f"[!] 骨架门禁（软）：{len(soft)} 项 —— 页面完好，但建卡纪律未完成：")
            for a, b in soft[:10]:
                print(f"       · {a}：{b}")
            print("       ⇒ 必须补链（CLAUDE.md §操作流程 6：出站≥2、入站≥1）。"
                  "工具**不替你补**（会凭空造出错关联），只登记缺口。")
        if rep:
            print(f"     门禁报告：{os.path.relpath(rep, K.VAULT)}")

        # 🆕 自动重跑去重清单（用户要求：入库后把新文献纳入下次去重）
        if written:
            print("\n[去重] 自动重跑 kb_dois.py + lit_catalogue.py …")
            # 新页名（去 .md）交给 kb_semantic_search.py --add
            new_pages = [os.path.basename(t)[:-3] for t in written]
            for name, ok2, summary in refresh_dedup(do_index=args.with_index,
                                                    new_pages=new_pages):
                mark = "ok  " if ok2 else "warn"
                print(f"  [{mark}] {name}: {summary}")
            print("     ⇒ 新文献已纳入下次 lit-watch 去重。")
        else:
            print("     （无新建页面，跳过去重清单重跑）")
        print("     下一步：补链 + 更新 index.md"
              + ("" if args.with_index else " + python tools/kb_build_index.py"))
        # 退出码契约（lit-watch skill / lit_batch 都要按它判断）：
        #   0 = 写完且门禁全过
        #   1 = 写坏（frontmatter 不可解析 / 回链文件不存在等**硬**问题）
        #   2 = 写好了，但有页面缺补链（**软**问题：出站<2 或入站 0）
        if hard:
            return 1
        if soft:
            return 2
        return 0
    else:
        print(f"\n（干跑结束，共 {len(planned)} 篇。确认后加 --apply）")
    return 0


if __name__ == "__main__":
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass
    sys.exit(main())
